grant execute on function pg_temp.candidate_fixture() to service_role;
set local role service_role;
do $$ declare q jsonb; begin
  for q in select value from jsonb_array_elements(pg_temp.candidate_fixture()->'queries') loop
    perform api.svc_result_query_stage_v2(q->'artifactRef',q->>'manifestText',q->'rows');
    perform api.svc_result_query_seal_v2((q#>>'{artifactRef,artifactId}')::uuid,jsonb_set(q->'receipt','{verifiedAt}',to_jsonb(clock_timestamp())));
  end loop;
end $$;
reset role;
create function pg_temp.candidate_args(p_candidate jsonb default '{}',p_catalog jsonb default '{}',p_receipt jsonb default '{}') returns jsonb language plpgsql as $$
declare c jsonb:=(pg_temp.candidate_fixture()->>'candidateText')::jsonb||p_candidate;
  d jsonb:=(pg_temp.candidate_fixture()->>'catalogText')::jsonb||p_catalog;
  r jsonb:=pg_temp.candidate_fixture()->'receipt'; t text; h text; files jsonb;
begin
  t:=d::text; h:=encode(extensions.digest(convert_to(t,'UTF8'),'sha256'),'hex');
  c:=jsonb_set(c,'{publicationCatalog,sha256}',to_jsonb(h));
  r:=jsonb_set(jsonb_set(r,'{candidateSha256}',to_jsonb(encode(extensions.digest(convert_to(c::text,'UTF8'),'sha256'),'hex'))),'{verifiedAt}',to_jsonb(clock_timestamp()));
  select jsonb_agg(file order by file->>'name') into files from (
    select jsonb_build_object('name','result.'||(value->>'format')||'.zip','sha256',value->'sha256','byteSize',value->'byteSize') file from jsonb_array_elements(c->'packages')
    union all select jsonb_build_object('name','release-candidate.json','sha256',r->'candidateSha256','byteSize',octet_length(c::text))
    union all select jsonb_build_object('name','publication-catalog.json','sha256',h,'byteSize',octet_length(t))
  ) f;
  return jsonb_build_object('candidateText',c::text,'catalogText',t,'receipt',jsonb_set(r,'{files}',files)||p_receipt);
end $$;
create function pg_temp.register_candidate(p_candidate jsonb default '{}',p_catalog jsonb default '{}',p_receipt jsonb default '{}') returns jsonb language plpgsql as $$
declare a jsonb:=pg_temp.candidate_args(p_candidate,p_catalog,p_receipt);
begin return api.svc_result_candidate_register_v2(a->>'candidateText',a->>'catalogText',a->'receipt'); end $$;
grant execute on function pg_temp.candidate_args(jsonb,jsonb,jsonb),pg_temp.register_candidate(jsonb,jsonb,jsonb) to service_role;
create temporary table original_args as select jsonb_set(pg_temp.candidate_fixture(),'{receipt,verifiedAt}',to_jsonb(clock_timestamp())) a;
grant select on original_args to service_role;
